/**
 * Phase 3 golden benchmark - curated JD cases with expected SEMANTIC properties.
 *
 * Every expectation here was written by reading the sentence and deciding what a hiring manager
 * means by it. None were generated by a model: an LLM-produced expected answer would make this
 * file a test of whether the engine agrees with a model rather than whether it reads English, and
 * the two failure modes it is supposed to catch - fabricated requirements and misread modality -
 * are exactly the ones a model would share with it.
 *
 * Cases are deliberately adversarial. Easy JDs never caught anything; the ones below are drawn
 * from the constructions that actually break keyword extractors: negation, double negation,
 * contrast clauses, modality that arrives after the subject, and the same token appearing twice at
 * two different strengths.
 */

import type { JobRecordInput } from './engine.js';
import type { RequirementLevel, Seniority } from './contract.js';

export interface GoldenCase {
  name: string;
  category: string;
  job: JobRecordInput;
  expect: {
    /** Subject must appear at exactly this level somewhere in requirements. */
    level?: { subject: string; level: RequirementLevel }[];
    /** Subject must NOT appear at this level - the anti-fabrication assertion. */
    notLevel?: { subject: string; level: RequirementLevel }[];
    /** Subject must not appear as a requirement at all. */
    absent?: string[];
    negated?: string[];
    experience?: { min?: number; max?: number | null; subject?: RegExp; type?: string }[];
    seniority?: Seniority | null;
    seniorityConfidenceNot?: string;
    capabilities?: string[];
    ambiguityTypes?: string[];
    contradictionTypes?: string[];
    context?: { subject: string; context: string }[];
    relationship?: { name: string; type: string; target: string }[];
  };
}

const jd = (title: string, description: string, extra: Partial<JobRecordInput> = {}): JobRecordInput =>
  ({ id: 1, title, description, ...extra });

