// ---------------------------------------------------------------- negation
const NEGATION: GoldenCase[] = [
  { name: 'is not required -> EXCLUDED', category: 'negation',
    job: jd('Backend Engineer', 'Python is not required.'),
    expect: { level: [{ subject: 'Python', level: 'EXCLUDED' }], negated: ['Python'],
      notLevel: [{ subject: 'Python', level: 'MANDATORY' }] } },
  { name: 'not mandatory -> EXCLUDED', category: 'negation',
    job: jd('Backend Engineer', 'Docker is not mandatory.'),
    expect: { level: [{ subject: 'Docker', level: 'EXCLUDED' }] } },
  { name: 'does not require -> EXCLUDED', category: 'negation',
    job: jd('Backend Engineer', 'This role does not require PHP.'),
    expect: { level: [{ subject: 'PHP', level: 'EXCLUDED' }] } },
  { name: 'no experience with X is required -> EXCLUDED', category: 'negation',
    job: jd('Backend Engineer', 'No experience with PHP is required.'),
    expect: { level: [{ subject: 'PHP', level: 'EXCLUDED' }] } },
  { name: 'not strictly required -> EXCLUDED', category: 'negation',
    job: jd('Backend Engineer', 'Kotlin is not strictly required.'),
    expect: { level: [{ subject: 'Kotlin', level: 'EXCLUDED' }] } },
  { name: 'double negative -> MANDATORY', category: 'negation',
    job: jd('Backend Engineer', 'Candidates without production Kubernetes experience will not be considered.'),
    expect: { level: [{ subject: 'Kubernetes', level: 'MANDATORY' }] } },
  { name: 'without ... need not apply -> MANDATORY', category: 'negation',
    job: jd('Backend Engineer', 'Applicants without Java need not apply.'),
    expect: { level: [{ subject: 'Java', level: 'MANDATORY' }] } },
  { name: 'only candidates with -> MANDATORY', category: 'negation',
    job: jd('Backend Engineer', 'Only candidates with Scala will be reviewed.'),
    expect: { level: [{ subject: 'Scala', level: 'MANDATORY' }] } },
  { name: 'negation scope does not reach earlier subject', category: 'negation',
    job: jd('Backend Engineer', 'Python is required. Kubernetes is not required.'),
    expect: { level: [{ subject: 'Python', level: 'MANDATORY' }, { subject: 'Kubernetes', level: 'EXCLUDED' }] } },
  { name: 'excluded requirement demands no evidence', category: 'negation',
    job: jd('Backend Engineer', 'Ruby is not required.'),
    expect: { level: [{ subject: 'Ruby', level: 'EXCLUDED' }] } },
];

